files.content:
:root {
  --bg: #1b1d2b;
  --bg-accent: #262a3f;
  --card: #f4f1e8;
  --ink: #1b1d2b;
  --accent: #ff5d8f;
  --accent-dark: #d63f70;
  --mint: #37d6a0;
  --muted: #6b6f85;
  --focus: #37d6a0;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  background-color: var(--bg);
  background-image:
    linear-gradient(45deg, var(--bg-accent) 25%, transparent 25%),
    linear-gradient(-45deg, var(--bg-accent) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, var(--bg-accent) 75%),
    linear-gradient(-45deg, transparent 75%, var(--bg-accent) 75%);
  background-size: 32px 32px;
  background-position: 0 0, 0 16px, 16px -16px, -16px 0;
  font-family: "Courier New", ui-monospace, Menlo, Consolas, monospace;
  font-size: 16px;
  color: var(--ink);
}

.wrap {
  width: 100%;
  max-width: 440px;
}

.card {
  background: var(--card);
  border: 4px solid var(--ink);
  box-shadow: 8px 8px 0 0 var(--ink);
  padding: 28px 24px;
}

.card-head {
  text-align: center;
  margin-bottom: 24px;
}

h1 {
  margin: 0;
  font-size: 28px;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.subtitle {
  margin: 8px 0 0;
  color: var(--muted);
  font-size: 16px;
}

.field {
  margin: 0 0 20px;
  padding: 0;
  border: 0;
}

label, legend {
  display: block;
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 8px;
  padding: 0;
}

input[type="number"] {
  width: 100%;
  font-family: inherit;
  font-size: 20px;
  padding: 12px;
  color: var(--ink);
  background: #fff;
  border: 3px solid var(--ink);
  box-shadow: 4px 4px 0 0 var(--ink);
  outline: none;
}

input[type="number"]:focus-visible {
  border-color: var(--accent-dark);
  box-shadow: 0 0 0 3px var(--focus);
}

.tip-row {
  display: flex;
  gap: 10px;
}

.tip-btn {
  flex: 1 1 0;
  font-family: inherit;
  font-size: 18px;
  font-weight: 700;
  padding: 12px 6px;
  cursor: pointer;
  color: var(--ink);
  background: #fff;
  border: 3px solid var(--ink);
  box-shadow: 4px 4px 0 0 var(--ink);
  transition: transform 0.05s ease, background 0.1s ease;
}

.tip-btn:hover {
  background: #ffe3ec;
}

.tip-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--focus);
}

.tip-btn:active {
  transform: translate(3px, 3px);
  box-shadow: 1px 1px 0 0 var(--ink);
}

.tip-btn[aria-pressed="true"] {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent-dark);
  box-shadow: 4px 4px 0 0 var(--accent-dark);
}

.tip-btn[aria-pressed="true"]:hover {
  background: var(--accent-dark);
}

.results {
  margin-top: 8px;
  border-top: 4px dashed var(--ink);
  padding-top: 20px;
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  padding: 8px 0;
  font-size: 18px;
}

.result-label { color: var(--muted); }
.result-value { font-weight: 700; }

.result-row.highlight {
  background: var(--ink);
  color: var(--card);
  padding: 12px;
  margin-top: 8px;
}

.result-row.highlight .result-label { color: var(--mint); }

.result-note {
  margin: 16px 0 0;
  font-size: 14px;
  color: var(--muted);
  text-align: center;
}

@media (max-width: 400px) {
  .card { padding: 20px 16px; }
  h1 { font-size: 24px; }
  .tip-row { gap: 8px; }
  .tip-btn { font-size: 16px; padding: 12px 4px; }
}

(function () {
  'use strict';

  var billInput = document.getElementById('bill');
  var peopleInput = document.getElementById('people');
  var tipButtons = Array.prototype.slice.call(
    document.querySelectorAll('.tip-btn')
  );
  var tipOut = document.getElementById('tip-out');
  var totalOut = document.getElementById('total-out');
  var perOut = document.getElementById('per-out');
  var note = document.getElementById('note');

  var selectedPercent = 0;

  function money(n) {
    return '$' + n.toFixed(2);
  }

  function setPressed(percent) {
    selectedPercent = percent;
    tipButtons.forEach(function (btn) {
      var active = Number(btn.getAttribute('data-percent')) === percent;
      btn.setAttribute('aria-pressed', active ? 'true' : 'false');
    });
  }

  function calculate() {
    var bill = parseFloat(billInput.value);
    var people = parseInt(peopleInput.value, 10);

    if (!isFinite(bill) || bill < 0) {
      tipOut.textContent = money(0);
      totalOut.textContent = money(0);
      perOut.textContent = money(0);
      note.textContent = 'Enter a valid bill amount to see results.';
      return;
    }

    if (!isFinite(people) || people < 1) {
      people = 1;
    }

    var tip = bill * (selectedPercent / 100);
    var total = bill + tip;
    var perPerson = total / people;

    tipOut.textContent = money(tip);
    totalOut.textContent = money(total);
    perOut.textContent = money(perPerson);

    if (selectedPercent === 0) {
      note.textContent = 'Pick a tip percent (10, 15 or 20).';
    } else {
      note.textContent =
        selectedPercent + '% tip split ' + people +
        (people === 1 ? ' way.' : ' ways.');
    }
  }

  tipButtons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      var percent = Number(btn.getAttribute('data-percent'));
      setPressed(percent === selectedPercent ? 0 : percent);
      calculate();
    });
  });

  billInput.addEventListener('input', calculate);
  peopleInput.addEventListener('input', calculate);

  // Start with 15% selected for a friendly default.
  setPressed(15);
  calculate();
})();
